//! Bounded stdout capture for local header inspection commands.
use std::{process::{Child,Command,Stdio},thread,sync::mpsc,io::{Read,Write},time::{Duration,Instant}};
struct Capture{child:Child,reader:Option<thread::JoinHandle<()>>}
impl Drop for Capture{fn drop(&mut self){let _=self.child.kill();let _=self.child.wait();if let Some(h)=self.reader.take(){let _=h.join();}}}
pub fn capture(cmd:&mut Command,max:usize,timeout:Duration)->Result<Vec<u8>,String>{
 if max==0||max>16*1024*1024||timeout.is_zero(){return Err("invalid capture bounds".into())}capture_bounded(cmd,max,timeout)
}
pub(crate) fn decode_capture(cmd:&mut Command,max:usize,deadline:Duration)->Result<Vec<u8>,String>{
 if max==0||max>256*1024*1024||deadline.is_zero(){return Err("invalid decode capture bounds".into())}capture_bounded(cmd,max,deadline)
}
pub(crate) fn decode_deadline(frames:usize)->Duration{Duration::from_secs(30u64.saturating_add((frames as u64).saturating_mul(2)).min(crate::guard::limits().timeout_s))}
fn capture_bounded(cmd:&mut Command,max:usize,timeout:Duration)->Result<Vec<u8>,String>{
 let deadline=Instant::now().checked_add(timeout).ok_or("capture deadline overflow")?;crate::guard::reserve(max+1);let mut child=cmd.stdout(Stdio::piped()).stderr(Stdio::null()).spawn().map_err(|e|e.to_string())?;let mut output=child.stdout.take().ok_or("capture stdout missing")?;let(tx,rx)=mpsc::channel();let reader=thread::spawn(move||{let mut bytes=Vec::with_capacity(max+1);let result=output.by_ref().take(max as u64+1).read_to_end(&mut bytes).map_err(|e|e.to_string()).and_then(|_|if bytes.len()>max{Err("capture stdout limit exceeded".into())}else{Ok(bytes)});let _=tx.send(result);});let mut c=Capture{child,reader:Some(reader)};
 let bytes=loop{crate::guard::check();let remaining=deadline.saturating_duration_since(Instant::now());if remaining.is_zero(){return Err("capture deadline exceeded".into())}match rx.recv_timeout(remaining.min(Duration::from_millis(100))){Ok(v)=>break v?,Err(mpsc::RecvTimeoutError::Timeout)=>continue,Err(_)=>return Err("capture reader disconnected".into())}};
 loop{crate::guard::check();if let Some(status)=c.child.try_wait().map_err(|e|e.to_string())?{if !status.success(){return Err("capture command failed".into())}return Ok(bytes)}let remaining=deadline.saturating_duration_since(Instant::now());if remaining.is_zero(){return Err("capture deadline exceeded after stdout".into())}thread::sleep(remaining.min(Duration::from_millis(20)));}
}
#[cfg(test)]mod tests{use super::*;
#[test]fn capture_success_and_limits(){assert_eq!(capture(Command::new("printf").arg("test"),100,Duration::from_secs(2)).unwrap(),b"test");assert!(capture(Command::new("printf").arg("long-output"),2,Duration::from_secs(2)).is_err());assert!(capture(&mut Command::new("false"),100,Duration::from_secs(2)).is_err());}
#[test]fn stalled_capture_is_reaped(){let path=std::env::temp_dir().join(format!("kimo-capture-pid-{}",std::process::id()));let script=format!("echo $$ > {}; exec sleep 30",path.display());let start=Instant::now();assert!(capture(Command::new("sh").args(["-c",&script]),1024,Duration::from_millis(100)).unwrap_err().contains("deadline"));assert!(start.elapsed()<Duration::from_secs(2));let id=std::fs::read_to_string(&path).unwrap();assert!(!std::path::Path::new(&format!("/proc/{}",id.trim())).exists());std::fs::remove_file(path).unwrap();}

#[test]fn decode_capture_limits_are_separate(){assert!(capture(Command::new("printf").arg("x"),16*1024*1024+1,Duration::from_secs(1)).is_err());assert_eq!(decode_capture(Command::new("printf").arg("x"),16*1024*1024+1,Duration::from_secs(1)).unwrap(),b"x");assert!(decode_capture(&mut Command::new("true"),256*1024*1024+1,Duration::from_secs(1)).is_err());assert!(decode_capture(&mut Command::new("true"),1,Duration::ZERO).is_err());assert!(decode_deadline(1)<=decode_deadline(100));assert!(decode_deadline(usize::MAX).as_secs()<=crate::guard::limits().timeout_s);}
#[test]fn normal_decode_capture_hash_and_bytes_match_prior_read(){use std::hash::{Hash,Hasher};let args=["-v","error","-f","lavfi","-i","testsrc2=s=32x16:r=25:d=0.4","-frames:v","10","-f","rawvideo","-pix_fmt","rgba","-"];let prior=Command::new("ffmpeg").args(args).output().unwrap();assert!(prior.status.success());let after=decode_capture(Command::new("ffmpeg").args(args),32*16*4*10,decode_deadline(10)).unwrap();assert_eq!(after.len(),32*16*4*10);let hash=|b:&[u8]|{let mut h=std::collections::hash_map::DefaultHasher::new();b.hash(&mut h);h.finish()};assert_eq!(hash(&prior.stdout),hash(&after));assert_eq!(prior.stdout,after);}
#[test]fn stalled_decode_capture_is_reaped(){let path=std::env::temp_dir().join(format!("kimo-decode-capture-pid-{}",std::process::id()));let script=format!("echo $$ > {}; exec sleep 30",path.display());let start=Instant::now();assert!(decode_capture(Command::new("sh").args(["-c",&script]),1024,Duration::from_millis(100)).unwrap_err().contains("deadline"));assert!(start.elapsed()<Duration::from_secs(2));let id=std::fs::read_to_string(&path).unwrap();assert!(!std::path::Path::new(&format!("/proc/{}",id.trim())).exists());std::fs::remove_file(path).unwrap();}
}

/// Rendezvous reader keeps at most main-held + worker-held raw frames.
pub(crate) struct DecodeStream{child:Child,rx:Option<mpsc::Receiver<Result<Option<Vec<u8>>,String>>>,reader:Option<thread::JoinHandle<()>>,deadline:Instant}
impl DecodeStream{
 pub(crate) fn new(cmd:&mut Command,frame_bytes:usize,frames:usize,timeout:Duration)->Result<Self,String>{
  if frame_bytes==0||frames==0||timeout.is_zero()||frame_bytes.checked_mul(frames).filter(|n|*n<=256*1024*1024).is_none(){return Err("invalid native stream bounds".into())}
  let deadline=Instant::now().checked_add(timeout).ok_or("native deadline overflow")?;
  crate::guard::reserve(frame_bytes.checked_mul(2).ok_or("native queue allocation overflow")?);
  let mut child=cmd.stdout(Stdio::piped()).stderr(Stdio::null()).spawn().map_err(|e|e.to_string())?;
  let mut output=child.stdout.take().ok_or("native stdout missing")?;let(tx,rx)=mpsc::sync_channel(0);
  let reader=thread::spawn(move||{for _ in 0..frames{let mut frame=vec![0u8;frame_bytes];let mut have=0;while have<frame_bytes{match output.read(&mut frame[have..]){Ok(0)=>break,Ok(n)=>have+=n,Err(e)=>{let _=tx.send(Err(e.to_string()));return}}}if have==0{let _=tx.send(Ok(None));return}if have!=frame_bytes{let _=tx.send(Err("truncated native decode".into()));return}if tx.send(Ok(Some(frame))).is_err(){return}}let _=tx.send(Ok(None));});
  Ok(Self{child,rx:Some(rx),reader:Some(reader),deadline})
 }
 pub(crate) fn next(&mut self)->Result<Option<Vec<u8>>,String>{loop{crate::guard::check();let remaining=self.deadline.saturating_duration_since(Instant::now());if remaining.is_zero(){return Err("native decode deadline exceeded".into())}match self.rx.as_ref().ok_or("native reader closed")?.recv_timeout(remaining.min(Duration::from_millis(100))){Ok(v)=>return v,Err(mpsc::RecvTimeoutError::Timeout)=>continue,Err(_)=>return Err("native reader disconnected".into())}}}
 pub(crate) fn finish(&mut self)->Result<(),String>{self.rx.take();loop{crate::guard::check();if let Some(status)=self.child.try_wait().map_err(|e|e.to_string())?{return if status.success(){Ok(())}else{Err("native media decode failed".into())}}let remaining=self.deadline.saturating_duration_since(Instant::now());if remaining.is_zero(){return Err("native decode deadline exceeded after stdout".into())}thread::sleep(remaining.min(Duration::from_millis(20)));}}
}
impl Drop for DecodeStream{fn drop(&mut self){self.rx.take();let _=self.child.kill();let _=self.child.wait();if let Some(reader)=self.reader.take(){let _=reader.join();}}}
#[cfg(test)]mod stream_tests{use super::*;
#[test]fn stream_exact_frames_and_partial_rejection(){let mut s=DecodeStream::new(Command::new("printf").arg("abcdefgh"),4,2,Duration::from_secs(2)).unwrap();assert_eq!(s.next().unwrap().unwrap(),b"abcd");assert_eq!(s.next().unwrap().unwrap(),b"efgh");assert!(s.next().unwrap().is_none());s.finish().unwrap();let mut s=DecodeStream::new(Command::new("printf").arg("abc"),4,1,Duration::from_secs(2)).unwrap();assert!(s.next().unwrap_err().contains("truncated"));}
#[test]fn stalled_stream_killed_reaped_and_joined(){let mut s=DecodeStream::new(Command::new("sleep").arg("30"),4,1,Duration::from_millis(100)).unwrap();let id=s.child.id();let start=Instant::now();assert!(s.next().unwrap_err().contains("deadline"));drop(s);assert!(start.elapsed()<Duration::from_secs(2));assert!(!std::path::Path::new(&format!("/proc/{id}")).exists());}
#[test]fn blocked_channel_drop_joins(){let s=DecodeStream::new(Command::new("printf").arg("abcdefgh"),4,2,Duration::from_secs(2)).unwrap();let id=s.child.id();thread::sleep(Duration::from_millis(40));let start=Instant::now();drop(s);assert!(start.elapsed()<Duration::from_secs(2));assert!(!std::path::Path::new(&format!("/proc/{id}")).exists());}
#[test]fn normal_native_stream_matches_previous_read(){for pix in ["rgba64le","gbrapf32le"]{let args=["-v","error","-f","lavfi","-i","testsrc2=s=32x16:r=25:d=0.4","-frames:v","10","-f","rawvideo","-pix_fmt",pix,"-"];let prior=Command::new("ffmpeg").args(args).output().unwrap();assert!(prior.status.success());let frame_bytes=32*16*if pix=="rgba64le"{8}else{16};let mut s=DecodeStream::new(Command::new("ffmpeg").args(args),frame_bytes,10,decode_deadline(10)).unwrap();let mut after=Vec::new();while let Some(frame)=s.next().unwrap(){after.extend(frame)}s.finish().unwrap();assert_eq!(after,prior.stdout);}}
}
#[cfg(test)]mod stream_exit_tests{use super::*;
#[test]fn stream_exit_deadline_after_stdout(){let mut s=DecodeStream::new(Command::new("sh").args(["-c","printf abcd; exec sleep 30"]),4,1,Duration::from_millis(100)).unwrap();let id=s.child.id();assert_eq!(s.next().unwrap().unwrap(),b"abcd");assert!(s.next().unwrap().is_none());assert!(s.finish().unwrap_err().contains("after stdout"));drop(s);assert!(!std::path::Path::new(&format!("/proc/{id}")).exists());}
#[test]fn stream_failed_exit_is_not_success(){let mut s=DecodeStream::new(Command::new("sh").args(["-c","printf abcd; exit 1"]),4,1,Duration::from_secs(2)).unwrap();assert_eq!(s.next().unwrap().unwrap(),b"abcd");assert!(s.next().unwrap().is_none());assert!(s.finish().is_err());}
}

/// Joined encoder writer, one acknowledged frame in flight, bounded stderr tail.
pub(crate) struct EncodeStream{child:Child,tx:Option<mpsc::SyncSender<Vec<u8>>>,ack:mpsc::Receiver<Result<(),String>>,writer:Option<thread::JoinHandle<()>>,errors:Option<thread::JoinHandle<()>>,stderr:std::sync::Arc<std::sync::Mutex<Vec<u8>>>,deadline:Instant,max_frame:usize}
pub(crate) fn encode_deadline(frames:usize)->Duration{Duration::from_secs(30u64.saturating_add((frames as u64).saturating_mul(2)).min(crate::guard::limits().export_timeout_s))}
impl EncodeStream{
 pub(crate) fn new(cmd:&mut Command,max_frame:usize,timeout:Duration)->Result<Self,String>{if max_frame==0||max_frame>256*1024*1024||timeout.is_zero(){return Err("invalid encoder bounds".into())}crate::guard::reserve(max_frame.checked_mul(2).ok_or("encoder buffer overflow")?);let deadline=Instant::now().checked_add(timeout).ok_or("encoder deadline overflow")?;
 let mut child=cmd.stdin(Stdio::piped()).stderr(Stdio::piped()).spawn().map_err(|e|e.to_string())?;let mut input=child.stdin.take().ok_or("encoder stdin missing")?;let mut errors=child.stderr.take().ok_or("encoder stderr missing")?;
 let stderr=std::sync::Arc::new(std::sync::Mutex::new(Vec::with_capacity(8192)));let sink=stderr.clone();let error_thread=thread::spawn(move||{let mut b=[0u8;1024];while let Ok(n)=errors.read(&mut b){if n==0{break}if let Ok(mut tail)=sink.lock(){let excess=tail.len().saturating_add(n).saturating_sub(8192);if excess>0{tail.drain(..excess);}tail.extend_from_slice(&b[..n]);}}});
 let(tx,rx)=mpsc::sync_channel::<Vec<u8>>(1);let(at,ack)=mpsc::channel();let writer=thread::spawn(move||{while let Ok(frame)=rx.recv(){let result=input.write_all(&frame).map_err(|e|e.to_string());let failed=result.is_err();if at.send(result).is_err()||failed{break}}});
 Ok(Self{child,tx:Some(tx),ack,writer:Some(writer),errors:Some(error_thread),stderr,deadline,max_frame})}
 fn diagnostic(&self,error:String)->String{let tail=self.stderr.lock().ok().map(|v|String::from_utf8_lossy(&v).trim().to_string()).unwrap_or_default();if tail.is_empty(){error}else{format!("{error}; encoder stderr: {tail}")}}
 fn check_exit(&mut self)->Result<(),String>{if let Some(status)=self.child.try_wait().map_err(|e|e.to_string())?{if let Some(h)=self.errors.take(){let _=h.join();}return Err(self.diagnostic(format!("encoder exited before completion: {status}")))}Ok(())}
 pub(crate) fn write(&mut self,frame:Vec<u8>)->Result<(),String>{if frame.len()!=self.max_frame{return Err("encoder frame size mismatch".into())}crate::guard::check();self.check_exit()?;self.tx.as_ref().ok_or("encoder closed")?.try_send(frame).map_err(|e|format!("encoder queue unavailable: {e}"))?;
 loop{crate::guard::check();self.check_exit()?;let remaining=self.deadline.saturating_duration_since(Instant::now());if remaining.is_zero(){return Err(self.diagnostic("encoder write deadline exceeded".into()))}match self.ack.recv_timeout(remaining.min(Duration::from_millis(100))){Ok(Ok(()))=>return Ok(()),Ok(Err(e))=>return Err(self.diagnostic(format!("encoder write failed: {e}"))),Err(mpsc::RecvTimeoutError::Timeout)=>continue,Err(_)=>return Err(self.diagnostic("encoder writer disconnected".into()))}}}
 pub(crate) fn finish(&mut self)->Result<(),String>{self.tx.take();loop{crate::guard::check();if let Some(status)=self.child.try_wait().map_err(|e|e.to_string())?{if let Some(h)=self.errors.take(){let _=h.join();}return if status.success(){Ok(())}else{Err(self.diagnostic(format!("encoder failed: {status}")))}}let remaining=self.deadline.saturating_duration_since(Instant::now());if remaining.is_zero(){return Err(self.diagnostic("encoder exit deadline exceeded".into()))}thread::sleep(remaining.min(Duration::from_millis(20)));}}
}
impl Drop for EncodeStream{fn drop(&mut self){self.tx.take();let _=self.child.kill();let _=self.child.wait();if let Some(h)=self.writer.take(){let _=h.join();}if let Some(h)=self.errors.take(){let _=h.join();}}}
#[cfg(test)]mod encoder_tests{use super::*;
#[test]fn stalled_stdin_deadline_reaps_writer(){let mut e=EncodeStream::new(Command::new("sleep").arg("30"),1024*1024,Duration::from_millis(100)).unwrap();let id=e.child.id();let start=Instant::now();assert!(e.write(vec![1;1024*1024]).unwrap_err().contains("deadline"));drop(e);assert!(start.elapsed()<Duration::from_secs(2));assert!(!std::path::Path::new(&format!("/proc/{id}")).exists());}
#[test]fn early_encoder_exit_preserves_bounded_stderr(){let mut e=EncodeStream::new(Command::new("sh").args(["-c","printf 'intentional encoder failure' >&2; exit 7"]),4,Duration::from_secs(2)).unwrap();thread::sleep(Duration::from_millis(30));let error=e.write(vec![1;4]).unwrap_err();assert!(error.contains("intentional encoder failure"),"{error}");assert!(error.contains("before completion"));}
#[test]fn finish_nonzero_exit_while_writer_inflight(){let mut e=EncodeStream::new(Command::new("sh").args(["-c","sleep 0.05; printf 'blocked writer exit' >&2; exit 9"]),1024*1024,Duration::from_secs(2)).unwrap();e.tx.as_ref().unwrap().try_send(vec![1;1024*1024]).unwrap();let error=e.finish().unwrap_err();assert!(error.contains("blocked writer exit"),"{error}");}
#[test]fn normal_writer_matches_prior_file_bytes(){let args=["-v","error","-y","-f","rawvideo","-pix_fmt","rgba","-s","16x16","-r","25","-i","-","-c:v","ffv1","-pix_fmt","gbrp16le"];let base=std::env::temp_dir().join(format!("kimo-encoder-base-{}.mkv",std::process::id()));let after=std::env::temp_dir().join(format!("kimo-encoder-after-{}.mkv",std::process::id()));let frames:Vec<Vec<u8>>=(0..10).map(|i|vec![i*20;16*16*4]).collect();let mut p=Command::new("ffmpeg").args(args).arg(&base).stdin(Stdio::piped()).spawn().unwrap();let mut input=p.stdin.take().unwrap();for frame in &frames{input.write_all(frame).unwrap()}drop(input);assert!(p.wait().unwrap().success());let mut e=EncodeStream::new(Command::new("ffmpeg").args(args).arg(&after),16*16*4,Duration::from_secs(10)).unwrap();for frame in frames{e.write(frame).unwrap()}e.finish().unwrap();let decode=|path:&std::path::Path|Command::new("ffmpeg").args(["-v","error","-i"]).arg(path).args(["-f","rawvideo","-pix_fmt","rgba64le","-"]).output().unwrap().stdout;assert_eq!(decode(&base),decode(&after));std::fs::remove_file(base).unwrap();std::fs::remove_file(after).unwrap();}
}
#[cfg(test)]mod encoder_unwind_test{use super::*;
#[test]fn writer_reaped_and_joined_on_unwind(){let mut id=0;let start=Instant::now();let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let e=EncodeStream::new(Command::new("sleep").arg("30"),1024*1024,Duration::from_secs(2)).unwrap();id=e.child.id();e.tx.as_ref().unwrap().try_send(vec![1;1024*1024]).unwrap();thread::sleep(Duration::from_millis(20));panic!("intentional cancellation unwind");}));assert!(result.is_err());assert!(start.elapsed()<Duration::from_secs(2));assert!(!std::path::Path::new(&format!("/proc/{id}")).exists());}
}
#[cfg(test)]mod encoder_tail_tests{use super::*;
#[test]fn stderr_tail_keeps_last_bytes_and_is_bounded(){let mut e=EncodeStream::new(Command::new("sh").args(["-c","head -c 20000 /dev/zero >&2; printf END-OF-ENCODER-ERROR >&2; exit 7"]),4,Duration::from_secs(2)).unwrap();let error=e.finish().unwrap_err();assert!(error.ends_with("END-OF-ENCODER-ERROR"));assert!(e.stderr.lock().unwrap().len()<=8192);assert!(error.len()<8300);}
#[test]fn wrong_frame_size_does_not_poison_encoder(){let path=std::env::temp_dir().join(format!("kimo-write-size-{}.txt",std::process::id()));let mut e=EncodeStream::new(Command::new("sh").args(["-c",&format!("exec cat > {}",path.display())]),4,Duration::from_secs(2)).unwrap();assert!(e.write(vec![1;3]).unwrap_err().contains("size mismatch"));e.write(b"test".to_vec()).unwrap();e.finish().unwrap();assert_eq!(std::fs::read(&path).unwrap(),b"test");std::fs::remove_file(path).unwrap();}
}

/// Bounded process exit wait for file-to-file work, with joined stderr drain.
pub(crate) fn wait_command(cmd:&mut Command,timeout:Duration)->Result<(),String>{
 if timeout.is_zero(){return Err("invalid process deadline".into())}let deadline=Instant::now().checked_add(timeout).ok_or("process deadline overflow")?;
 let mut child=cmd.stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::piped()).spawn().map_err(|e|e.to_string())?;
 let mut errors=child.stderr.take().ok_or("process stderr missing")?;let(tx,rx)=mpsc::channel();
 let reader=thread::spawn(move||{let mut tail=Vec::with_capacity(8192);let mut b=[0u8;1024];while let Ok(n)=errors.read(&mut b){if n==0{break}let excess=tail.len().saturating_add(n).saturating_sub(8192);if excess>0{tail.drain(..excess);}tail.extend_from_slice(&b[..n]);}let _=tx.send(tail);});
 let mut owner=Capture{child,reader:Some(reader)};
 let result=(||{loop{crate::guard::check();if let Some(status)=owner.child.try_wait().map_err(|e|e.to_string())?{return if status.success(){Ok(())}else{Err(format!("process failed: {status}"))}}let remaining=deadline.saturating_duration_since(Instant::now());if remaining.is_zero(){return Err("process deadline exceeded".into())}thread::sleep(remaining.min(Duration::from_millis(100)));}})();
 let _=owner.child.kill();let _=owner.child.wait();if let Some(h)=owner.reader.take(){let _=h.join();}let tail=rx.try_recv().unwrap_or_default();result.map_err(|e|{let tail=String::from_utf8_lossy(&tail);if tail.trim().is_empty(){e}else{format!("{e}; process stderr: {}",tail.trim())}})
}
#[cfg(test)]mod wait_tests{use super::*;
#[test]fn file_command_failure_tail_is_bounded(){let error=wait_command(Command::new("sh").args(["-c","head -c 20000 /dev/zero >&2; printf FINAL-MUX-ERROR >&2; exit 7"]),Duration::from_secs(2)).unwrap_err();assert!(error.ends_with("FINAL-MUX-ERROR"));assert!(error.len()<8300);}
#[test]fn wait_timeout_reaps_real_process(){let path=std::env::temp_dir().join(format!("kimo-wait-pid-{}",std::process::id()));let error=wait_command(Command::new("sh").args(["-c",&format!("echo $$ > {}; exec sleep 30",path.display())]),Duration::from_millis(100)).unwrap_err();assert!(error.contains("deadline"));let id=std::fs::read_to_string(&path).unwrap();assert!(!std::path::Path::new(&format!("/proc/{}",id.trim())).exists());std::fs::remove_file(path).unwrap();}
}
